import{_ as a,o as t,c as r,a2 as c}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"Interrupts and exceptions","description":"","frontmatter":{},"headers":[],"relativePath":"arch/interrupts.md","filePath":"arch/interrupts.md"}'),i={name:"arch/interrupts.md"};function o(s,e,n,d,h,p){return t(),r("div",null,[...e[0]||(e[0]=[c('<h1 id="interrupts-and-exceptions" tabindex="-1">Interrupts and exceptions <a class="header-anchor" href="#interrupts-and-exceptions" aria-label="Permalink to &quot;Interrupts and exceptions&quot;">​</a></h1><h2 id="tables" tabindex="-1">Tables <a class="header-anchor" href="#tables" aria-label="Permalink to &quot;Tables&quot;">​</a></h2><p><code>kernel/arch/x86_64/arch_idt.{c,h}</code>: a 256-entry IDT with interrupt gates; a new GDT with a TSS; IST1 = panic stack (#DF/#MC get their own stack - never a context switch on IST2, which is the dedicated exception-exit stack, BUG-0139); IST2 = debug stack.</p><h2 id="pic-and-lapic" tabindex="-1">PIC and LAPIC <a class="header-anchor" href="#pic-and-lapic" aria-label="Permalink to &quot;PIC and LAPIC&quot;">​</a></h2><p><code>arch_irq.c</code> remaps the 8259 to vectors 32-47 (IRQ0-15). The local APIC handling lives in <code>arch_lapic.c</code>. The IRQ lines are visible in-guest via <code>irqabitest</code>.</p><h2 id="exception-path" tabindex="-1">Exception path <a class="header-anchor" href="#exception-path" aria-label="Permalink to &quot;Exception path&quot;">​</a></h2><p>The stubs (<code>arch_idt_stub.S</code>) build a frame, dispatch by vector: page-fault growth (stack/heap), syscall entry (int 0x80 family -&gt; <code>core_syscall.c</code>), device IRQs, and the crash path for anything unhandled: register dump to serial, crashlog to /etc, halt.</p><p>The boot-time self-test fires #DE, #UD and #PF deliberately and asserts the kernel survives - <code>exception self-test: 3/3</code> is on every boot log, so a broken trap path never makes it to a shell prompt.</p><h2 id="time-sources" tabindex="-1">Time sources <a class="header-anchor" href="#time-sources" aria-label="Permalink to &quot;Time sources&quot;">​</a></h2><p>PIT (the tick), HPET, ACPI PM timer, TSC, CMOS RTC - each with a command (<code>timer</code>, <code>hpet</code>, <code>pmtimer</code>, <code>tsc</code>, <code>rtc</code>) and a bring-up manual page under <a href="./../drivers/">../drivers/</a>.</p>',10)])])}const m=a(i,[["render",o]]);export{u as __pageData,m as default};
